sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var enableTradeLink = gs.getProperty('x_hsb11_mss_c_proc.mssCustodyLinkTradesForBulk', 'false');
        if (String(enableTradeLink) !== 'true') return;

        var trade = current.getValue('trade_id');

        var gettrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        if (gettrade.get(trade)) {
            var bulk = gettrade.getValue('associated_bulk_id');

            var getTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            if (getTask.get(current.sys_id)) {
                getTask.setValue('bulk_id', bulk);
                getTask.update();
            }

            // var bulkGR = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            // if (bulkGR.get(bulk)) {
            //     if (bulkGR.redesigned_bulk.toString() == 'true') {
            //         current.setValue('bulk_id', bulk);
            //         current.update();
            //     }
            // }
        }

    } catch (e) {
        gs.info('error in update bulk id field.' + e.message);
    }

})(current, previous);
